import{_ as t,C as r,o as l,c as s,j as i,E as n,a as e,a3 as d}from"./chunks/framework.C6R8kWFE.js";const k=JSON.parse(`{"title":"2-hafta","description":"","frontmatter":{"title":"2-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"10-sinf (BI & ML)","link":"/10-sinf-bi/"},"n":2,"bob":"I-bob · Ma’lumotlar muhandisligiga kirish va ma’lumotlarni boshqarish","lessons":[{"g":4,"title":"4-dars: Ma’lumot formatlari: Parquet va Columnar saqlash formati (Snappy siqish, CSV vs Parquet)","lead":"Katta hajmdagi ma'lumotlar olamida saqlash joyi va o'qish tezligi hal qiluvchi ahamiyatga ega. Ushbu darsda biz zamonaviy analitika poydevori bo'lgan Apache Parquet formatining ichki mo'jizalarini, ustunli saqlash tamoyilini va Snappy siqish qudratini o'rganamiz.","link":"/10-sinf-bi/hafta-02/dars-1","slide":"/slaydlar/10-sinf-bi/hafta-02/dars-1.html","test":"/slaydlar/10-sinf-bi/hafta-02/dars-1-test.html"},{"g":5,"title":"5-dars: Ma’lumot formatlari: Avro va formatlarni chuqur taqqoslash","lead":"Real-time rejimida millionlab voqealarni uzatishda har bir bayt hisobda turadi. Ushbu darsda biz Apache Kafka va oqimli tizimlarning sevimlisi bo'lgan Apache Avro formatini hamda Data Engineeringdagi \\"Katta to'rtlik\\" (CSV, JSON, Parquet, Avro) formatlarining o'zaro raqobatini o'rganamiz.","link":"/10-sinf-bi/hafta-02/dars-2","slide":"/slaydlar/10-sinf-bi/hafta-02/dars-2.html","test":"/slaydlar/10-sinf-bi/hafta-02/dars-2-test.html"},{"g":6,"title":"6-dars: Ma’lumotlar bazalari: konsept va tuzilma. Relatsion ma’lumotlar bazasi (RDBMS) asoslari","lead":"Bugungi raqamli iqtisodiyot — bu milliardlab bog'langan ma'lumotlar oqimidir. Har bir bank o'tkazmasi, har bir xarid va har bir avtorizatsiya ortida ma'lumotlar bazasi va uning qat'iy qoidalari turadi. Ushbu darsda biz nima uchun fayllar davri o'tib, RDBMS (Relatsion ma'lumotlar bazalari) dunyoni boshqarayotganini, Edgar Codd kashfiyotini, ACID tamoyillarini hamda SQL qudratini o'rganamiz.","link":"/10-sinf-bi/hafta-02/dars-3","slide":"/slaydlar/10-sinf-bi/hafta-02/dars-3.html","test":"/slaydlar/10-sinf-bi/hafta-02/dars-3-test.html"}],"test":"/slaydlar/10-sinf-bi/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"10-sinf-bi/hafta-02/index.md","filePath":"10-sinf-bi/hafta-02/index.md"}`),m={name:"10-sinf-bi/hafta-02/index.md"},u={class:"blk"},h={id:"uyga-vazifa",tabindex:"-1"};function b(f,a,c,q,g,v){const o=r("Icon");return l(),s("div",null,[i("div",u,[i("h2",h,[n(o,{name:"house"}),a[0]||(a[0]=e(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>Mazkur haftada o&#39;tilgan darslar (Parquet, Avro va RDBMS asoslari) bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h3 id="_4-dars-ma-lumot-formatlari-parquet-va-columnar-saqlash-formati" tabindex="-1">4-dars: Ma’lumot formatlari: Parquet va Columnar saqlash formati <a class="header-anchor" href="#_4-dars-ma-lumot-formatlari-parquet-va-columnar-saqlash-formati" aria-label="Permalink to &quot;4-dars: Ma’lumot formatlari: Parquet va Columnar saqlash formati&quot;">​</a></h3><ol><li><strong>Format konvertatsiyasi:</strong> O&#39;zingiz qiziqqan soha (futbol statistikasi, ob-havo, e-tijorat yoki maktab baholari) bo&#39;yicha kamida 50 000 qatorlik CSV dataset toping yoki yarating. Uni Python Pandas yordamida Parquet (<code>compression=&#39;snappy&#39;</code>) formatiga o&#39;tkazing.</li><li><strong>Benchmark tahlili:</strong> <code>os.path.getsize()</code> va <code>time</code> moduli yordamida ikkala fayl hajmini hamda bitta ustun bo&#39;yicha o&#39;rtacha qiymat (<code>mean()</code>) hisoblash vaqtini o&#39;lchang.</li><li><strong>Hisobot:</strong> CSV va Parquet natijalarini (hajm, tezlik, tejalgan disk maydoni foizi) taqqoslovchi kichik 1 betlik tahliliy hisobot tayyorlang.</li></ol><hr><h3 id="_5-dars-ma-lumot-formatlari-avro-va-formatlarni-chuqur-taqqoslash" tabindex="-1">5-dars: Ma’lumot formatlari: Avro va formatlarni chuqur taqqoslash <a class="header-anchor" href="#_5-dars-ma-lumot-formatlari-avro-va-formatlarni-chuqur-taqqoslash" aria-label="Permalink to &quot;5-dars: Ma’lumot formatlari: Avro va formatlarni chuqur taqqoslash&quot;">​</a></h3><ol><li><strong>Avro sxemasi loyihalash:</strong> Foydalanuvchi profili uchun <code>user.avsc</code> JSON sxemasini yozing. Unda: <code>user_id</code> (long), <code>username</code> (string), <code>email</code> (string), <code>status</code> (enum: &quot;ACTIVE&quot;, &quot;BANNED&quot;, &quot;PENDING&quot;) va ixtiyoriy <code>telefon</code> (union: [&quot;null&quot;, &quot;string&quot;], default: null) bo&#39;lsin.</li><li><strong>fastavro amaliyoti:</strong> Python <code>fastavro</code> kutubxonasi yordamida kamida 3 nafar namunaviy foydalanuvchini ushbu sxema asosida <code>users.avro</code> fayliga yozing va qayta o&#39;qib konsolga chiqaring.</li><li><strong>Formatlar tanlovi:</strong> 3 xil real ssenariy (Streaming loglar, Data Warehouse analitikasi, Foydalanuvchi mobil sozlamalari) uchun mos formatni (CSV, JSON, Parquet, Avro) tanlang va sababini tushuntiring.</li></ol><hr><h3 id="_6-dars-ma-lumotlar-bazalari-konsept-va-tuzilma-relatsion-ma-lumotlar-bazasi-rdbms-asoslari" tabindex="-1">6-dars: Ma’lumotlar bazalari: konsept va tuzilma. Relatsion ma’lumotlar bazasi (RDBMS) asoslari <a class="header-anchor" href="#_6-dars-ma-lumotlar-bazalari-konsept-va-tuzilma-relatsion-ma-lumotlar-bazasi-rdbms-asoslari" aria-label="Permalink to &quot;6-dars: Ma’lumotlar bazalari: konsept va tuzilma. Relatsion ma’lumotlar bazasi (RDBMS) asoslari&quot;">​</a></h3><ol><li><strong>ERD loyihalash:</strong> O&#39;zingiz bilgan real tizim (kutubxona, avtosalon, poliklinika yoki mehmonxona) uchun kamida 3 ta jadvaldan iborat relyatsion model (ER-diagramma) chizing.</li><li><strong>Kalitlar va cheklovlar:</strong> Modelda qaysi ustunlar Primary Key, qaysilari Foreign Key ekanligini aniq ko&#39;rsating va relyatsion yaxlitlik qoidalarini belgilang.</li><li><strong>Python va SQLite amaliyoti:</strong> Python <code>sqlite3</code> moduli yordamida ushbu 3 ta jadvalni yaratuvchi, har biriga kamida 2 tadan yozuv qo&#39;shuvchi va <code>INNER JOIN</code> orqali birlashgan hisobot chiqaruvchi skript yozing.</li></ol><hr>',11))])])}const z=t(m,[["render",b]]);export{k as __pageData,z as default};
